import{_ as s,H as n,f as i,i as e}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"01 | 数据处理：把企业知识组织起来","description":"","frontmatter":{},"headers":[{"level":2,"title":"分析业务需求，找到业务需要的数据，确定数据流向","slug":"分析业务需求-找到业务需要的数据-确定数据流向","link":"#分析业务需求-找到业务需要的数据-确定数据流向","children":[]},{"level":2,"title":"统一不同数据源的数据，选型 LLM 和向量数据库","slug":"统一不同数据源的数据-选型-llm-和向量数据库","link":"#统一不同数据源的数据-选型-llm-和向量数据库","children":[]},{"level":2,"title":"数据建模，实现数据使用流程","slug":"数据建模-实现数据使用流程","link":"#数据建模-实现数据使用流程","children":[]},{"level":2,"title":"保持数据更新和质量监控","slug":"保持数据更新和质量监控","link":"#保持数据更新和质量监控","children":[{"level":3,"title":"做好数据更新，维护好数据","slug":"做好数据更新-维护好数据","link":"#做好数据更新-维护好数据","children":[]},{"level":3,"title":"监控数据质量，剔除无效 / 低效内容","slug":"监控数据质量-剔除无效-低效内容","link":"#监控数据质量-剔除无效-低效内容","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"LLM&RAG快速应用小册/01｜数据处理：把企业知识组织起来.md","filePath":"LLM&RAG快速应用小册/01｜数据处理：把企业知识组织起来.md","lastUpdated":1795530671000}'),t={name:"LLM&RAG快速应用小册/01｜数据处理：把企业知识组织起来.md"};function l(p,a,o,c,h,d){return n(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="_01-数据处理-把企业知识组织起来" tabindex="-1">01 | 数据处理：把企业知识组织起来 <a class="header-anchor" href="#_01-数据处理-把企业知识组织起来" aria-label="Permalink to &quot;01 | 数据处理：把企业知识组织起来&quot;">​</a></h1><ul><li>本门课程为精品小课，不标配音频</li></ul><p>万丈高楼平地起，想要做好企业大模型应用，数据就是地基。</p><p>你好，我是王吕，今天我们正式开始第一讲的学习。大模型想要变成生产力，目前还有两个制约因素，第一个是交互过程中的长文本，第二个是内容的实时更新，RAG 就是为解决这两个问题诞生的。</p><p>在传统的应用开发中，我们写程序是把数据一条一条存进数据库中，这可能是关系型数据库，也可能是非关系型数据库，数据库保留了应用的全部记忆。而在 AI 时代，向量数据库（Vector Database）充当了这一角色，在 RAG 系统中，数据通常被转换为高维向量形式，使得语言模型能够进行高效的语义相似度计算和检索。在向量数据库中，查找变成了计算每条记录的向量近似度，然后按照分值倒序返回结果。RAG 就是如何存取向量的方法论，根据不同的实现策略，还衍生出了不同的 RAG 技术，比如利用图结构表示和检索知识的 GraphRAG，结合知识图谱增强生成能力的 KGA2G（Knowledge Graph Augmented Generation）等等。</p><p>尽管 AI 应用的数据建模与传统应用有相似之处，但它更强调数据的语义表示和关联性，以支持更灵活的查询和推理。因此，高质量的数据处理不仅影响检索的准确性，还直接决定了语言模型生成内容的质量和可靠性。这正是我们将数据处理作为整个课程首要内容的原因。</p><p>接下来，我分享一下极客时间组织数据的一些方法和经验，我们一起学习。</p><h2 id="分析业务需求-找到业务需要的数据-确定数据流向" tabindex="-1">分析业务需求，找到业务需要的数据，确定数据流向 <a class="header-anchor" href="#分析业务需求-找到业务需要的数据-确定数据流向" aria-label="Permalink to &quot;分析业务需求，找到业务需要的数据，确定数据流向&quot;">​</a></h2><p>以极客时间小助手的对话场景为例，在对话过程中，小助手会根据用户问题找到对应文章相关的段落，再根据段落文章内容给出回答，同时找到相关的专栏推荐给用户。根据这个需求场景，我们能梳理出来整个过程使用了三种数据。</p><ol><li><p>文章数据：这部分数据需要根据用户问题进行向量检索，所以这部分数据是需要向量化的。</p></li><li><p>课程数据：这里其实就可以有多种处理方案，一是由于第一个步骤我们拿到了文章数据，可以根据引用的文章找到所属的课程，得到课程数据；二是可以把用户的提问和最终答案组合到一起，对课程进行向量检索，找到跟问题最相关的课程。这两种方式都可以，根据业务选择即可，这里我们使用第二个方案举例。</p></li><li><p>对话数据：我们需要知道用户之前的对话上下文，所以提供给 LLM 的数据中也要包含历史对话。</p></li></ol><p>找到了需求所需的数据之后，我们就可以确定如何存取这些数据的流程。</p><ul><li><p>针对文章和专栏数据，最终的数据源一定是来自极客时间的数据库，并且这部分数据还要进行向量化，使用的过程都是通过向量进行检索。</p></li><li><p>针对对话数据，目前最简单的方案是读取对话列表的前 N（极客时间默认取 3 条）条记录，和文章数据一起组成上下文，不需要向量化，直接用传统数据库就能搞定。在后续章节中，我会介绍一些更好的方案。</p></li></ul><p>经过上述分析，文章数据和专栏数据是需要进行建模和向量化，做进一步处理的。</p><h2 id="统一不同数据源的数据-选型-llm-和向量数据库" tabindex="-1">统一不同数据源的数据，选型 LLM 和向量数据库 <a class="header-anchor" href="#统一不同数据源的数据-选型-llm-和向量数据库" aria-label="Permalink to &quot;统一不同数据源的数据，选型 LLM 和向量数据库&quot;">​</a></h2><p>上边的数据需求有点简单，实际应用中，可能你的数据会来自数据库，也可能是钉钉文档，或者是 WPS 文档，甚至可能是一堆 PPT 或者音视频。</p><p>这里，我们的思路是：先把所有内容转成文本（毕竟我们只是使用“大语言模型”）+ 额外数据（用来关联数据）的方式，然后我们选择一个 Embedding 模型，把文本转成向量，配合关联数据存储到向量数据库中。</p><p>关于常见的 Embedding 模型，我整理了如下列表，作为参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%26RAG%E5%BF%AB%E9%80%9F%E5%BA%94%E7%94%A8%E5%B0%8F%E5%86%8C/images/01/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%26RAG%E5%BF%AB%E9%80%9F%E5%BA%94%E7%94%A8%E5%B0%8F%E5%86%8C/images/01/1.png" alt=""></a></p><p>之后我们来选择向量数据库，我把常见的向量数据库及其特性也整理了一下，供你参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%26RAG%E5%BF%AB%E9%80%9F%E5%BA%94%E7%94%A8%E5%B0%8F%E5%86%8C/images/01/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%26RAG%E5%BF%AB%E9%80%9F%E5%BA%94%E7%94%A8%E5%B0%8F%E5%86%8C/images/01/2.png" alt=""></a></p><p>目前极客时间使用的向量数据库是 Qdrant，性能强，使用简单，上手容易，本地开发搭建方便，SDK 也很完整。</p><h2 id="数据建模-实现数据使用流程" tabindex="-1">数据建模，实现数据使用流程 <a class="header-anchor" href="#数据建模-实现数据使用流程" aria-label="Permalink to &quot;数据建模，实现数据使用流程&quot;">​</a></h2><p>接下来，我会使用 Qdrant 作为案例。不过在开始建模之前，我先简单讲解一下 Qdrant 的数据结构。</p><p>Tips：每个向量都需要提前设置维度，向量表现在计算机上就是一个 float 数组，维度就是数组长度。</p><p>Qdrant 的 collection 对应了数据库的表，Point 对应了一条记录，Point 由 3 部分组成：唯一ID、向量和 Payload 数据。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 项目地址: https://github.com/qdrant/qdrant</span></span>
<span class="line"><span>// 源码位置: lib/collection/src/operations/point_ops.rs</span></span>
<span class="line"><span>pub struct PointStruct {</span></span>
<span class="line"><span>   /// Point id 每条记录的唯一 ID</span></span>
<span class="line"><span>   pub id: PointIdType,</span></span>
<span class="line"><span>   /// Vectors 存储的向量,向量维度(数组长度)是创建 collection 的时候确定的</span></span>
<span class="line"><span>   #[serde(alias = &quot;vectors&quot;)]</span></span>
<span class="line"><span>   #[validate]</span></span>
<span class="line"><span>   pub vector: VectorStruct,</span></span>
<span class="line"><span>   /// Payload values (optional) 记录携带的数据，理论上可以带任意值</span></span>
<span class="line"><span>   pub payload: Option&lt;​Payload&gt;,</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Qdrant 的简单使用，可以参考这篇文章。</p><p>整个数据处理流程如下图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%26RAG%E5%BF%AB%E9%80%9F%E5%BA%94%E7%94%A8%E5%B0%8F%E5%86%8C/images/01/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%26RAG%E5%BF%AB%E9%80%9F%E5%BA%94%E7%94%A8%E5%B0%8F%E5%86%8C/images/01/3.png" alt=""></a></p><p>下面我们开始设计“文章 / 课程”数据模型，这里有几点经验可以分享一下。</p><ol><li><p>由于向量数据库还在高速发展阶段，很多东西可能会有变化，如果选定数据库之后，可以多关注官网的更新日志，留意一些特性和 Bug 修复，万一我们也碰到了这个 Bug 呢？</p></li><li><p>往向量数据库写数据的时候，是把文本先转成向量，再带上对应的数据写入，向量没办法手动修改。如果在测试阶段，不要全量写入，这样会带来大量的 Embedding 费用。如果文本切片规则变动的话，也会涉及到全量的 collection 更新，这样基本上就是新建一个collection 了，成本也很高，需要关注一下。</p></li><li><p>collection 的向量维度是要跟 Embedding 模型保持一致的，不同的 Embedding 模型生成的限量维度可能不一样，需要注意一下，写入同一个 collection 和读取的 Embedding 应该是同一个。</p></li><li><p>我们可以自定义的地方就是 payload，但是尽量不要在 payload 中存储长文本，只放一些关键的 ID 数据，把确定性的信息还是用传统数据库保存，两种数据库配合使用。</p></li><li><p>线上环境使用 Qdrant 执行分布式部署的时候，需要注意一下</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>write_consistency_factor 这个参数，这个参数用来设置副本数量，类似 Kafka 的副</span></span></code></pre></div><ul><li>本，需要在一致性和性能上找一个平衡。</li></ul><ol start="6"><li>通常为了设计的通用性，在大模型应用中，把传进来的长文，可能是文章，也可能是课程介绍，统一抽象叫做“文档（document）”，文档拆分之后的每个小块叫做“节点（node）”，也就是切片。</li></ol><p>综上，文章数据的 payload 就可以设计成：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;document_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">，</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 文档 ID</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;node_id&quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">，</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 文本所属节点节点 ID</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>同时，还要使用传统数据库（如 MySQL）保存一些文档的属性。</p><ul><li>文档记录表：主要保存文档的相关属性。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>document_id  文档 ID</span></span>
<span class="line"><span>node_count 拆分的节点数量</span></span>
<span class="line"><span>algorithm 拆分的算法类型，可以是固定长度，还可以是按照 \\n 换行... 下节详细讲这里</span></span>
<span class="line"><span>source_type 文档来源</span></span>
<span class="line"><span>source_id 原文档对应的 ID</span></span>
<span class="line"><span>content 可以保存一份文档副本，用来追溯排查问题</span></span></code></pre></div><ul><li>节点记录表：保存每个切片的属性。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>document_id 文档 ID</span></span>
<span class="line"><span>node_id 切片 ID</span></span>
<span class="line"><span>node_order 切片的顺序 (可选记录)，方便做一些复杂的功能</span></span>
<span class="line"><span>text 切片内容</span></span>
<span class="line"><span>... 也可以增加一些其他额外数据，记录这个切片的信息，根据业务情况</span></span></code></pre></div><p>有了以上数据模型之后，任意的文档过来，经过上述处理流程保存到 Qdrant 中，都可以被关联查询。</p><h2 id="保持数据更新和质量监控" tabindex="-1">保持数据更新和质量监控 <a class="header-anchor" href="#保持数据更新和质量监控" aria-label="Permalink to &quot;保持数据更新和质量监控&quot;">​</a></h2><h3 id="做好数据更新-维护好数据" tabindex="-1">做好数据更新，维护好数据 <a class="header-anchor" href="#做好数据更新-维护好数据" aria-label="Permalink to &quot;做好数据更新，维护好数据&quot;">​</a></h3><p>构建好上述数据处理流程之后，还需要把整个过程做成接口或者脚本可以触发的应用，这样后续有新文章更新的时候，自动触发更新数据流程。</p><h3 id="监控数据质量-剔除无效-低效内容" tabindex="-1">监控数据质量，剔除无效 / 低效内容 <a class="header-anchor" href="#监控数据质量-剔除无效-低效内容" aria-label="Permalink to &quot;监控数据质量，剔除无效 / 低效内容&quot;">​</a></h3><p>等到应用运行之后，我们还要定期关注数据质量。比如，切片是否切出了无效切片，类似“好的”、“Java” 这些切片文字很少，而且单词含义很广、很常见，这种切片在查询向量数据库的时候，可能会得到一个很高的评分，最终污染上下文。我们要在文档切片的时候，增加一些数据清洗的步骤，尽量过滤掉这些情况，当然这就跟业务相关了，需要持续观察，制定对应的清洗策略。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>开发大模型应用，首先要做好数据基础。</p><p>在需求分析阶段，我们按照「查找依赖数据 -&gt; 分析哪些需要向量化 -&gt; 归类数据处理流程」的步骤，提炼出我们要维护和使用的数据流程。</p><p>之后在实施阶段，我们首先要统一不同来源的数据。然后确定一个向量数据库，标准是满足性能需求和之前的数据需求。接下来就开始数据建模，这里的数据建模是需要反复尝试的，可能要尝试多种切片算法，一遍一遍地做，直到得到效果符合要求的策略，这里是非常考验耐心的，有时候一个切片长度就需要调好长时间，不过既然准备涉足新领域了，我相信你也做好了准备！</p><p>当然最终还要建立一套机制，用来维护数据和监控数据的质量。上线之后，也要持续观察，甚至那时才会发现文档切片的问题，不过没关系，持续优化它！</p><p>以上是极客时间在处理数据的一些经验和心得，你还有哪些技巧？欢迎在评论区分享讨论！</p>`,53)])])}const g=s(t,[["render",l]]);export{u as __pageData,g as default};
